package me.rezapour.f1appserver.apiimport me.rezapour.f1appserver.api.model.DriverDtoimport me.rezapour.f1appserver.api.model.DriversResponseimport org.springframework.stereotype.Componentimport org.springframework.web.client.RestClient@Componentclass F1ApiClient(    private val restClientBuilder: RestClient.Builder) {    private val client = restClientBuilder        .baseUrl("https://api.jolpi.ca")        .build()    fun getDrivers(): List<DriverDto>? {        return client.get()            .uri("/ergast/f1/drivers/")            .retrieve()            .body(DriversResponse::class.java)            ?.data?.driverTable?.drivers    }}